  stroke-width="{{ (p.StrokeWidth ?? 0) ?: 2 }}" stroke-linecap="round" stroke-linejoin="round"
  class="{{ ui_cn(['inline-block shrink-0', p.Class ?? '']) }}"
  {%- if label == '' %} aria-hidden="true"{% else %} aria-label="{{ label }}" role="img"{% endif %} data-slot="icon"
